    ('5503', 'Vehicle', 'expense', 'Dep. - Vehicle', 2),
    ('5504', 'Plant', 'expense', 'Dep. - Plant', 3),
    ('5505', 'Computer / Office Equip', 'expense', 'Dep. - Computer / Office Equip', 4),
    ('5401', 'Vehicle', 'expense', 'Vehicle Expenses', 5),
    ('4401', 'Rent', 'income', 'Rent Income', 6),
    ('5308', 'Rent', 'expense', 'Rent Expense', 7),
    ('4402', 'Transport', 'income', 'Transport Income', 8),
    ('5103', 'Transport', 'expense', 'Transport Expense', 9)
  ) as v(id, old_name, type, new_name, ord)
    on a.id = v.id and trim(a.name) = v.old_name and a.type = v.type
 where not exists (select 1 from public.accounts o
                    where o.society_id = a.society_id and o.type = a.type and o.id <> a.id
